def download(url, dest):
    if os.path.exists(dest) and os.path.getsize(dest) > 1000:
        print(f"  SKIP {os.path.basename(dest)} (already exists)")
        return True
    req = urllib.request.Request(url, headers=HEADERS)
    try:
        with urllib.request.urlopen(req, timeout=60) as resp, open(dest, "wb") as f:
            data = resp.read()
            f.write(data)
        size_kb = os.path.getsize(dest) // 1024
        print(f"  OK   {os.path.basename(dest)} ({size_kb}KB)")
        return True
    except Exception as e:
        print(f"  ERR  {os.path.basename(dest)}: {e}")
        return False


total_ok = 0
total_err = 0

for prospect, posts in MEDIA.items():
    img_dir = os.path.join(BASE, prospect, "img")
    os.makedirs(img_dir, exist_ok=True)
    print(f"\n{'='*50}")
    print(f"  {prospect}")
    print(f"{'='*50}")

    for key, post in posts.items():
        n = key[-1]  # "1", "2", "3"
        t = post["type"]

        if t == "image":
            ok = download(post["thumb"], os.path.join(img_dir, f"top{n}_thumb.jpg"))
            total_ok += ok; total_err += (not ok)

        elif t == "video":
            ok1 = download(post["thumb"], os.path.join(img_dir, f"top{n}_thumb.jpg"))
            ok2 = download(post["mp4"], os.path.join(img_dir, f"top{n}.mp4"))
            total_ok += ok1 + ok2; total_err += (not ok1) + (not ok2)

        elif t == "carousel":
            for i, url in enumerate(post["slides"], start=1):
                ok = download(url, os.path.join(img_dir, f"top{n}_slide{i}.jpg"))
                total_ok += ok; total_err += (not ok)
            # First slide as thumb too
            ok = download(post["slides"][0], os.path.join(img_dir, f"top{n}_thumb.jpg"))
            total_ok += ok; total_err += (not ok)

print(f"\n{'='*50}")
print(f"DONE — {total_ok} OK, {total_err} ERR")
